\label{th:plucker}
If $C\subset {\mathbb{P}}^n$ is  a curve of genus  $g$, then 
\begin{center}
$d_{l+1}-2d_l+d_{l-1}=2g-2-b_l$, for all $1\leq l\leq n-1$,
\end{center}
where $d_{-1}=d_n=0$.

\label{th:hyperosc}
\mbox{}
\begin{enumerate}
\item The set of hyperosculating points of $\C{k}{n-2}{\lambda}$ is $F$. 
\item  If $p\in F$, then $b_1(p)=k-2$ and $b_l(p)=k-1$,  $l \in \{2,\ldots, n-1\}$.
\end{enumerate}

\label{co:hyperosc}
Let $z$ be  a local chart of  $\C{k}{n-2}{\lambda}$  around the point  $p\in \C{k}{n-2}{\lambda}$. Then the normal form of 
$f_0$ in  $z(p):=0$  is given as follows.
\begin{enumerate}
\item If $p\in F$, then 
$$f_0(z)=[1:z: g_0(z^{k}):g_1(z^{k}):\cdots :g_{i}(z^{k}):\cdots : g_{n-1}(z^{k})],$$
where the  $g_i$ are holomorphic functions such that $g_i(z)=z^{i+1}+\cdots+\cdots$.

\item If $p\not \in F$, then  
$$f_0(z)=[1:z: z^2+\cdots :\cdots : z^{(n-1)}+\cdots].$$
\end{enumerate}

\label{ej:bound}
Consider the following generalized Fermat curve of the type $(5,3)$  
\begin{center}
$C^5(-1):=\left \{ \begin{array}{rcc}
x_0^5+x_1^5+x_2^5&=&0\\
-x_0^5+x_1^5+x_3^5&=&0
\end{array}\right .$
\end{center}
and $p=[1:1:-\sqrt[5]{2}:0]$. 
In this case, $\hat{w}(p)<w(p)$.  In Section \ref{Sec:finalejemplo} we provide a proof of this fact.

